/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
internal final class AVAProdSetupReleaseRecordController  extends SysOperationServiceController
{
}

Method.Source:
public static AVAProdSetupReleaseRecordController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAProdSetupReleaseRecordController controller;
    controller = new AVAProdSetupReleaseRecordController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVAProdSetupReleaseRecordController controller;
    AVAProdSetupReleaseRecordContract contract;
    ProdTable prodTable;

    controller = AVAProdSetupReleaseRecordController::construct();
    if (_args.record() && _args.dataset() == tableNum(ProdTable))
    {
        prodTable = _args.record();
        contract = controller.getDataContractObject();
        contract.parmProdId(prodTable.ProdId);
    }
    else
    {
        throw Error(Error::missingRecord(tableStr(ProdTable)));
    }
    controller.parmArgs(_args);
    controller.startOperation();
}
